  function byId(id){for(var i=0;i<MODELS.length;i++)if(MODELS[i].id===id)return MODELS[i];return null;}
  function cat(id){for(var i=0;i<CATS.length;i++)if(CATS[i].id===id)return CATS[i];return null;}
  function group(id){for(var i=0;i<EXTRA.length;i++)if(EXTRA[i].id===id)return EXTRA[i];return null;}
  function inCat(c,sub){return MODELS.filter(function(m){return m.cat===c&&(!sub||m.sub===sub);});}
  function hits(){return MODELS.filter(function(m){return m.hit;});}
  function money(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,' ');}
  function priceText(m){return m.price?'от '+money(m.price)+' \u20bd':'цена по запросу';}
